async function gql(admin, query, variables, tries = 4) {
  for (let i = 0; i < tries; i++) {
    const res = await admin.graphql(query, { variables });
    const json = await res.json();

    const throttled = json.errors?.some((e) => e.extensions?.code === "THROTTLED");
    if (!throttled) return json;

    const { requestedQueryCost, throttleStatus } = json.extensions.cost;
    const missing = requestedQueryCost - throttleStatus.currentlyAvailable;
    const waitMs = Math.ceil((missing / throttleStatus.restoreRate) * 1000) + 100;
    await new Promise((r) => setTimeout(r, waitMs));
  }
  throw new Error("Throttled demais");
}

fragment ProductRow on Product {
  id title status totalInventory
}

query Catalog($cursor: String, $search: String) {
  products(first: 100, after: $cursor, query: $search) {
    nodes { ...ProductRow }
    pageInfo { hasNextPage endCursor }
  }
}
